import { Component, computed, Input as HostBinding } from '@angular/core';

@Component({
  selector: 'pct-avatar',
  templateUrl: './avatar.html',
  host: {
    '[tabindex]': 'order()',
  },
})
export class PctAvatar {
  @HostBinding() readonly order = computed(() => 0);
}
